import { and, eq } from "drizzle-orm";
import { db, playerProgressTable, progressionEventsTable } from "@workspace/db";
import { wingRewardCredits, type WingRewardOutcome } from "./wing-reward-policy";

export type WingRewardReceipt = {
  awarded: boolean;
  amount: number;
  balanceAfter: number;
  outcome: WingRewardOutcome;
};

/**
 * Grants a server-adjudicated Wing match reward once per player and match.
 * The match id is generated by the socket server; no client-provided balance
 * or reward amount is accepted. Each player grant is one database transaction.
 */
export async function awardWingMatchReward(input: {
  userId: string;
  matchId: string;
  outcome: WingRewardOutcome;
  team: 0 | 1;
}): Promise<WingRewardReceipt> {
  const { userId, matchId, outcome, team } = input;
  const idempotencyKey = `wing:${matchId}`;
  const amount = wingRewardCredits(outcome);

  return db.transaction(async (tx) => {
    await tx.insert(playerProgressTable).values({ userId }).onConflictDoNothing();
    const [profile] = await tx
      .select()
      .from(playerProgressTable)
      .where(eq(playerProgressTable.userId, userId))
      .for("update");
    if (!profile) throw new Error("Player profile could not be loaded for Wing reward.");

    const [previous] = await tx
      .select()
      .from(progressionEventsTable)
      .where(and(
        eq(progressionEventsTable.userId, userId),
        eq(progressionEventsTable.idempotencyKey, idempotencyKey),
      ));
    if (previous) {
      const result = previous.result as { source?: string; outcome?: string };
      if (result.source !== "wing" || result.outcome !== outcome) {
        throw new Error("Wing reward idempotency key conflicts with an existing progression event.");
      }
      return {
        awarded: false,
        amount: previous.amount,
        balanceAfter: previous.balanceAfter,
        outcome,
      };
    }

    const balanceAfter = profile.credits + amount;
    if (!Number.isSafeInteger(balanceAfter)) throw new Error("Wing reward balance exceeds the safe integer range.");
    const [updated] = await tx
      .update(playerProgressTable)
      .set({ credits: balanceAfter, revision: profile.revision + 1, updatedAt: new Date() })
      .where(eq(playerProgressTable.userId, userId))
      .returning();
    if (!updated) throw new Error("Player profile could not be updated for Wing reward.");

    await tx.insert(progressionEventsTable).values({
      userId,
      idempotencyKey,
      kind: "wing_reward",
      amount,
      balanceBefore: profile.credits,
      balanceAfter,
      result: { source: "wing", matchId, outcome, team },
    });

    return { awarded: true, amount, balanceAfter, outcome };
  });
}
